// ------------------------------------------------------------
// COVER PAGE
// ------------------------------------------------------------
#let fmt-cover(paper) = {
  page(
    paper: "a4",
    margin: (top: 12mm, bottom: 12mm, left: ML, right: ML),
    header: none,
    footer: none,
  )[
    // Name / Class table — 2x2 bordered grid, top right corner
    #align(right + top)[
      #table(
        columns: (auto, 55mm),
        align: (left + horizon, left + horizon),
        stroke: (thickness: 0.6pt, paint: black),
        inset: (x: 2mm, y: 2mm),
        row-gutter: 0mm,
        column-gutter: 0mm,

        text(size: 12pt, font: "Times New Roman", weight: "bold")[Name:],
        text(size: 12pt, font: "Times New Roman")[ ],
        text(size: 12pt, font: "Times New Roman", weight: "bold")[Date:],
        text(size: 12pt, font: "Times New Roman")[ ]
      )
    ]

    #v(15mm)

    // Title block centered
    #align(center)[
      #text(size: 28pt, font: "Times New Roman", weight: "bold")[#paper.title]
    ]
    #v(5mm)
    #align(center)[
      #text(size: 18pt, font: "Times New Roman", weight: "bold")[#paper.subject]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 14pt, font: "Times New Roman")[#paper.paper-type]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 12pt, font: "Times New Roman", style: "italic")[#paper.language-note]
    ]

    #v(6mm)

    #box(
      fill: rgb("#F5F5F5"),
      inset: (x: 4mm, y: 3mm),
      stroke: (thickness: 0.6pt, paint: black),
      width: 100%,
    )[
      #text(size: 11pt, font: "Times New Roman", weight: "bold")[INSTRUCTIONS]
      #v(2mm)
      #set par(justify: false)
      #set text(size: 10pt, font: "Times New Roman")
      #for (i, item) in paper.instructions.enumerate() [
        #{i + 1}. #item
        #if i < paper.instructions.len() - 1 { v(1mm) }
      ]
    ]

    #align(center + bottom)[
      #text(size: 9pt, font: "Times New Roman", fill: rgb("#555555"))[#paper.footer-credit]
    ]
  ]
}

