// ============================================================
// DSE Mini Mock — Main Entry Point
// ============================================================
//
// To create a new paper variant:
//   1. Edit the paper config below (title, instructions, etc.).
//   2. Edit content.typ with the questions for your paper.
//   3. Compile:  typst compile main.typ output.pdf
//
// main.typ     — per-paper metadata (title, instructions, page count)
// content.typ  — question data
// style.typ    — visual formatting (shared across papers)
// ============================================================

#import "style.typ": make-paper
#import "content.typ": exam-content

// ---- Per-paper configuration ----
#let paper = (
  title: [Final Exam Mock 1],
  subject: [Form 1 Mathematics],
  paper-type: [Paper 1 — Question-Answer Book],
  language-note: [This paper must be answered in English,],
  instructions: (
    [Write your Name and Class in the spaces provided at the top of this page.],
    [This paper consists of THREE sections, A(1), A(2) and B.],
    [Attempt ALL questions in this paper. Write your answers in the spaces provided in this Question-Answer Book. Do not write in the margins.],
    [Graph paper and supplementary answer sheets will be supplied on request. Write your Name and mark the question number box on each sheet, and fasten them with string INSIDE this book.],
    [Unless otherwise specified, all working must be clearly shown.],
    [Unless otherwise specified, numerical answers should be either exact or correct to 3 significant figures.],
    [The diagrams in this paper are not necessarily drawn to scale.],
  ),
  footer-credit: [Mr. T Yeung 2026],
  pages-total: 24,
)

#make-paper(paper, exam-content)
